async function armNativeSong(songIndex:number):Promise<NativeReadyState>{
  if(statusTimer){clearInterval(statusTimer);statusTimer=null;}
  await engine.closeAndWait();engine=new NativeEngineClient();
  engine.on("transport",(state:NativeTransportState)=>{performance?.updatePosition(state.positionSeconds);sendToRenderer("playback:transport",state);sendToRenderer("performance:state",performance?.snapshot);const now=Date.now();if(now-lastControlPublish>=100){lastControlPublish=now;controlBus?.publishState();}});
  engine.on("fault",(error:Error)=>{performance?.reportFault(error.message);sendToRenderer("performance:state",performance?.snapshot);controlBus?.publishState();});
  engine.on("midi-input",(event:NativeMidiInputEvent)=>{void midiInputRouter?.handle(event);sendToRenderer("control:midi-input",event);});
  engine.on("meters",(meters:NativeMixerMeters)=>sendToRenderer("mixer:meters",meters));
  const ready=await engine.start(enginePath,manifestPath,songIndex,selectedMidiOutput,selectedAudioDevice,selectedMidiInput,selectedAudioRouting??undefined);
  statusTimer=setInterval(()=>engine.requestStatus(),33);return ready;
}

