app.on("before-quit", () => { if (statusTimer) clearInterval(statusTimer); engine.close();void remoteServer?.close(); });
function listMidiOutputs():Promise<string[]>{return new Promise((resolveList,reject)=>execFile(enginePath,["--list-midi"],{windowsHide:true},(error,stdout)=>error?reject(error):resolveList(stdout.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))));}
function listAudioDevices():Promise<NativeAudioDeviceSelection[]>{return new Promise((resolveList,reject)=>execFile(enginePath,["--list-audio-devices"],{windowsHide:true},(error,stdout)=>error?reject(error):resolveList(stdout.split(/\r?\n/).map(line=>line.split("\t")).filter(parts=>parts.length===2).map(([type,name])=>({type:type!,name:name!})))));}
function sameAudioDevice(left:NativeAudioDeviceSelection,right:NativeAudioDeviceSelection):boolean{return left.type===right.type&&left.name===right.name;}
async function listMidiInputs():Promise<string[]>{return new Promise((resolveList,reject)=>execFile(enginePath,["--list-midi-inputs"],{windowsHide:true},(error,stdout)=>error?reject(error):resolveList(stdout.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))));}
async function saveDeviceSettings():Promise<void>{await mkdir(join(projectRoot,".playback-data"),{recursive:true});await writeFile(join(projectRoot,".playback-data","device-settings.json"),JSON.stringify({midiOutputName:selectedMidiOutput,midiInputName:selectedMidiInput,audioDevice:selectedAudioDevice,audioRouting:selectedAudioRouting,updatedAt:new Date().toISOString()},null,2));}
function defaultAudioRouting(stemCount:number):NativeAudioRouting{return{stems:Array.from({length:stemCount},(_,index)=>index+1),stemChannels:Array.from({length:stemCount},()=>1 as const),click:19,cue:20,pad:21,iem:31};}
function validateAudioRouting(routing:NativeAudioRouting,stemCount:number):void{if(!routing||!Array.isArray(routing.stems)||routing.stems.length!==stemCount||!Array.isArray(routing.stemChannels)||routing.stemChannels.length!==stemCount)throw new Error("Routing must include every prepared stem");const validate=(label:string,start:number,width:number)=>{if(!Number.isInteger(start)||start<0||start>32||(start>0&&start+width-1>32))throw new Error(`${label} must be unassigned or routed within Dante outputs 1-32`);};routing.stems.forEach((output,index)=>{const width=routing.stemChannels[index];if(width!==1&&width!==2)throw new Error(`Stem ${index+1} must be mono or stereo`);validate(`Stem ${index+1}`,output,width);});validate("Click",routing.click,1);validate("Cues",routing.cue,1);validate("Pad",routing.pad,1);validate("IEM",routing.iem,1);}
function testMidiOutput(name:string):Promise<void>{return new Promise((resolveTest,reject)=>execFile(enginePath,["--test-midi-output",name],{windowsHide:true},error=>error?reject(error):resolveTest()));}
function sendMidiBytes(name:string,bytes:readonly number[]):Promise<void>{return new Promise((resolveSend,reject)=>execFile(enginePath,["--send-midi-output",name,...bytes.map(value=>value.toString(16).padStart(2,"0"))],{windowsHide:true},error=>error?reject(error):resolveSend()));}
type ControlSettings={token:string;httpPort:number;oscPort:number;lanEnabled:boolean;oscEnabled:boolean;footControllerProfile:FootControllerProfileId;gld:{host:string;port:number;midiChannel:number;midiOutputName:string|null;writesEnabled:boolean};updatedAt:string};
async function loadOrCreateControlSettings():Promise<ControlSettings>{const path=join(projectRoot,".playback-data","control-settings.json");try{const value=JSON.parse(await readFile(path,"utf8"));if(typeof value.token==="string"&&value.token.length>=16)return{token:value.token,httpPort:Number.isInteger(value.httpPort)?value.httpPort:38191,oscPort:Number.isInteger(value.oscPort)?value.oscPort:38192,lanEnabled:value.lanEnabled===true,oscEnabled:value.oscEnabled!==false,footControllerProfile:value.footControllerProfile==="basic-notes"?"basic-notes":"disabled",gld:{host:typeof value.gld?.host==="string"?value.gld.host:"",port:51325,midiChannel:Number.isInteger(value.gld?.midiChannel)?value.gld.midiChannel:1,midiOutputName:typeof value.gld?.midiOutputName==="string"?value.gld.midiOutputName:null,writesEnabled:false},updatedAt:typeof value.updatedAt==="string"?value.updatedAt:new Date().toISOString()};}catch{}const settings:ControlSettings={token:randomBytes(24).toString("base64url"),httpPort:38191,oscPort:38192,lanEnabled:false,oscEnabled:true,footControllerProfile:"disabled",gld:{host:"",port:51325,midiChannel:1,midiOutputName:null,writesEnabled:false},updatedAt:new Date().toISOString()};await writeControlSettings(settings);return settings;}
async function writeControlSettings(settings:ControlSettings):Promise<void>{await mkdir(join(projectRoot,".playback-data"),{recursive:true});await writeFile(join(projectRoot,".playback-data","control-settings.json"),JSON.stringify(settings,null,2));}
function controlUrls(settings:ControlSettings,address:RemoteControlAddress|null):string[]{if(!address)return[];const hosts=settings.lanEnabled?Object.values(networkInterfaces()).flatMap(items=>(items??[]).filter(item=>item.family==="IPv4"&&!item.internal).map(item=>item.address)):["127.0.0.1"];return[...new Set(hosts)].map(host=>`http://${host}:${address.httpPort}/?token=${encodeURIComponent(settings.token)}`);}
function toPlaybackCommand(value:any):PlaybackCommand{if(value.action==="play")return{type:"transport.play"};if(value.action==="pause")return{type:"transport.pause"};if(value.action==="stop")return{type:"transport.stop"};if(value.action==="panic")return{type:"panic.enter"};if(value.action==="recover")return{type:"panic.recover",regionId:value.regionId};if(value.action==="jump")return{type:"section.jump",regionId:value.regionId};if(value.action==="next-section")return{type:"section.next"};if(value.action==="previous-section")return{type:"section.previous"};if(value.action==="loop")return{type:"section.loop",regionId:value.regionId??performance!.snapshot.currentRegionId??""};if(value.action==="repeat-once")return{type:"section.repeat-once",regionId:value.regionId??performance!.snapshot.currentRegionId??""};if(value.action==="cue-next")return{type:"song.cue-next"};if(value.action==="bus")return{type:"bus.set",bus:value.bus,enabled:value.enabled};if(value.action==="gain")return{type:"bus.gain",bus:value.bus,gain:value.gain};if(value.action==="mixer-channel")return{type:"mixer.channel",index:value.index,gain:value.gain,muted:value.muted,solo:value.solo,iem:value.iem};if(value.action==="mixer-master")return{type:"mixer.master",gain:value.gain};if(value.action==="song")return{type:"song.select",index:value.index};throw new Error("Unknown performance command");}
async function listPreparedArrangements(active:ConfirmedSetManifest):Promise<{name:string;path:string}[]>{const result=[{name:"Original Song",path:originalManifestPath}];try{const{readdir}=await import("node:fs/promises");for(const directory of await readdir(join(projectRoot,".playback-cache","arrangements"),{withFileTypes:true})){if(!directory.isDirectory())continue;const path=join(projectRoot,".playback-cache","arrangements",directory.name,"performance","confirmed-set.json");try{const prepared=JSON.parse(await readFile(path,"utf8"));if(prepared.songs?.[0]?.song?.id===active.songs[0]?.song.id)result.push({name:prepared.name??directory.name,path});}catch{}}}catch{}return result.filter((item,index,array)=>array.findIndex(other=>other.path===item.path)===index);}
async function allPreparedManifestPaths():Promise<string[]>{const paths=[originalManifestPath];try{const{readdir}=await import("node:fs/promises");for(const directory of await readdir(join(projectRoot,".playback-cache","arrangements"),{withFileTypes:true}))if(directory.isDirectory())paths.push(join(projectRoot,".playback-cache","arrangements",directory.name,"performance","confirmed-set.json"));}catch{}return paths;}
function sendToRenderer(channel:string,payload:unknown):void{if(!window||window.isDestroyed()||window.webContents.isDestroyed())return;window.webContents.send(channel,payload);}
function safeCacheName(value:string){const normalized=value.replace(/[^a-z0-9._-]+/gi,"-").replace(/^-|-$/g,"")||"song";return normalized.length<=72?normalized:`${normalized.slice(0,32)}-${normalized.slice(-32)}`;}
function isPreparedManifestPath(path:string):boolean{const cacheRoot=resolve(projectRoot,".playback-cache"),rel=relative(cacheRoot,path);return rel!==""&&!rel.startsWith("..")&&!isAbsolute(rel)&&path.toLowerCase().endsWith("confirmed-set.json");}
function padKey(key:string){const aliases:Record<string,string>={"C#":"Db","D#":"Eb","F#":"Gb","G#":"Ab","A#":"Bb"};return aliases[key]??key;}
async function cuePreviewData(label:string,song:any):Promise<string>{const existing=song.liveAssets?.cues?.find((cue:any)=>cue.label===label)?.audioPath;if(existing)return`data:audio/wav;base64,${(await readFile(existing)).toString("base64")}`;const normalized=label.replace(/([A-Za-z])([0-9])$/,"$1 $2").replace(/^Turnaround/i,"Turn Around"),aliases:Record<string,string>={START:"CountIn.wav"},names=[aliases[normalized.toUpperCase()]??`${normalized.toUpperCase()}.wav`,`${normalized.toUpperCase().replace(/\s+/g,"")}.wav`];for(const name of names){const path=join(productionDefaults.cueFolder,name);try{return`data:audio/wav;base64,${(await readFile(path)).toString("base64")}`;}catch{}}const match=normalized.match(/^(.*)\s+([1-6])$/);if(!match)throw new Error(`No cue audio for ${label}`);const numbers=["ZERO","ONE","TWO","THREE","FOUR","FIVE","SIX"],base=join(productionDefaults.cueFolder,`${match[1]!.toUpperCase()}.wav`),number=join(productionDefaults.cueFolder,`${numbers[Number(match[2])]}.wav`);const bytes=await new Promise<Buffer>((resolveBytes,reject)=>execFile("ffmpeg",["-hide_banner","-loglevel","error","-i",base,"-i",number,"-filter_complex","[0:a][1:a]concat=n=2:v=0:a=1[out]","-map","[out]","-f","wav","pipe:1"],{encoding:"buffer",maxBuffer:16*1024*1024},(error,stdout)=>error?reject(error):resolveBytes(stdout as Buffer)));return`data:audio/wav;base64,${bytes.toString("base64")}`;}
